fn MaxDifference(a: Vec<i64>) -> i64 {
    assert!(
        a.len() >= 2,
        "Input vector must contain at least two elements"
    );

    // Initialize min and max to the first element
    let mut min_val = a[0];
    let mut max_val = a[0];

    // Scan through the rest of the elements
    for &x in &a[1..] {
        if x < min_val {
            min_val = x;
        }
        if x > max_val {
            max_val = x;
        }
    }

    // The maximum difference between any two elements is max_val - min_val
    max_val - min_val
}

